/** Editable per-data-point label fields. Omit a field to leave it unchanged. */
interface ChartDataPointLabelEdit {
  /** Show the numeric value (`c:showVal`). */
  showValue?: boolean;
  /** Show the category name (`c:showCatName`). */
  showCategory?: boolean;
  /** Show the series name (`c:showSerName`). */
  showSeriesName?: boolean;
  /** Show the percentage (`c:showPercent`). */
  showPercent?: boolean;
  /** Show the legend key swatch (`c:showLegendKey`). */
  showLegendKey?: boolean;
  /** Label position (`c:dLblPos`). */
  position?: PptxChartDataLabel['position'];
  /** Custom label text override (`c:tx`). Pass `''` to clear it. */
  text?: string;
  /**
   * This label's own shape formatting (`c:dLbl/c:spPr`: fill/line colour,
   * width, dash style). Pass `null` to remove it, merging into the existing
   * override when both are set.
   */
  spPr?: PptxChartShapeProps | null;
  /**
   * This label's own font (`c:dLbl/c:txPr`). Pass `null` to remove it,
   * merging into the existing override when both are set.
   */
  txPr?: PptxChartDataLabel['txPr'] | null;
}
/**
 * Set (or clear) the individual data-label override for a single data point of a
 * series, independent of the series-level data labels. Round-trips to the saved
 * `.pptx` (`c:dLbl` keyed by `c:idx` inside the series' `c:dLbls`).
 *
 * Pass a {@link ChartDataPointLabelEdit} to add/merge the override for that
 * point, or `null` to remove it (reverting the point to the series default).
 *
 * @param element - The chart element to modify.
 * @param seriesIndex - Zero-based index of the series.
 * @param pointIndex - Zero-based index of the data point (category).
 * @param edit - The label fields to set, or `null` to remove the override.
 * @throws {RangeError} If `seriesIndex` is out of bounds.
 *
 * @example
 * ```ts
 * setChartDataPointLabel(chartEl, 0, 2, { showValue: true, position: "outEnd" });
 * setChartDataPointLabel(chartEl, 0, 2, { text: "Peak" });
 * setChartDataPointLabel(chartEl, 0, 2, null); // remove the override
 * ```
 */
declare function setChartDataPointLabel(element: ChartPptxElement, seriesIndex: number, pointIndex: number, edit: ChartDataPointLabelEdit | null): void;
//#endregion
//#region src/core/builders/sdk/chart-formatting-operations.d.ts
/**
 * Set (or clear) the full shape formatting (fill colour, stroke colour,
 * stroke width, stroke dash style) of a single data point, overriding the
 * series' own styling for that point only. Round-trips to the saved `.pptx`
 * (`c:dPt/c:spPr` keyed by `c:idx`), including the stroke width/dash style
 * that {@link import('./chart-operations').setChartDataPointFill} does not
 * expose (it only ever sets `fillColor`).
 *
 * Pass a {@link PptxChartShapeProps} patch to merge into the point's existing
 * style, or `null` to remove it entirely (dropping the whole `c:dPt`
 * override when nothing else is set on it).
 *
 * @example
 * ```ts
 * setChartDataPointStyle(chartEl, 0, 2, { strokeColor: "#FF0000", strokeWidth: 2, strokeDashStyle: "dash" });
 * setChartDataPointStyle(chartEl, 0, 2, null); // clear
 * ```
 */
declare function setChartDataPointStyle(element: ChartPptxElement, seriesIndex: number, pointIndex: number, style: PptxChartShapeProps | null): void;
/**
 * Set (or remove) a chart-level helper line: `c:dropLines` (line/stock
 * charts) or `c:hiLowLines` (line/stock charts, joins the high/low points).
 * Round-trips to the saved `.pptx`.
 *
 * Pass a {@link PptxChartLineStyle} to set/replace the line's colour, width,
 * and dash style (an empty `{}` shows the line with default styling), or
 * `null` to remove the element entirely.
 *
 * @throws {Error} If the chart is not a line, stock, or combo chart.
 *
 * @example
 * ```ts
 * setChartHelperLine(chartEl, "hiLowLines", { color: "#888888", width: 0.75 });
 * setChartHelperLine(chartEl, "dropLines", null); // remove
 * ```
 */
declare function setChartHelperLine(element: ChartPptxElement, line: 'dropLines' | 'hiLowLines', style: PptxChartLineStyle | null): void;
/**
 * Set (or clear) the chart's colour-map override (`c:clrMapOvr`), remapping
 * up to 12 theme colour roles (`bg1`, `tx1`, `bg2`, `tx2`, `accent1`-`accent6`,
 * `hlink`, `folHlink`) for this chart only. Round-trips to the saved `.pptx`.
 *
 * Pass a partial map to merge into any existing override, or `null` to
 * remove it entirely so the chart falls back to the deck's own colour map.
 *
 * @example
 * ```ts
 * setChartColorMapOverride(chartEl, { accent1: "accent2", accent2: "accent1" });
 * setChartColorMapOverride(chartEl, null); // remove
 * ```
 */
